import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CdTmk4Xw.js";const u=JSON.parse('{"title":"CodeFlare · Project documentation","description":"","frontmatter":{"editLink":true},"headers":[],"relativePath":"repository.md","filePath":"repository.md"}'),r={name:"repository.md"};function o(n,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="codeflare-·-project-documentation" tabindex="-1">CodeFlare · Project documentation <a class="header-anchor" href="#codeflare-·-project-documentation" aria-label="Permalink to &quot;CodeFlare · Project documentation&quot;">​</a></h1><p>CodeFlare is a competitive programming archive of C++ solutions, templates, and practice, organized by online judge and contest. This branch, <code>docs/project-guide</code>, maintains project guides, the static problem browser&#39;s API contracts, and the VitePress documentation site.</p><p><a href="https://codeflare.lucius7.dev" target="_blank" rel="noreferrer">Website</a> · <a href="https://codeflare.lucius7.dev/docs/" target="_blank" rel="noreferrer">Online documentation</a> · <a href="https://github.com/xw7qwq/solutions" target="_blank" rel="noreferrer">Source repository</a> · <a href="./catalog.html">Source catalog</a> · <a href="./contributing.html">Contributing</a></p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Guide</th></tr></thead><tbody><tr><td>Integrate problem data and look up fields or error conventions</td><td><a href="./api/">API reference</a></td></tr><tr><td>Find platforms, templates, and tools</td><td><a href="./structure.html">Project structure</a>, <a href="./catalog.html">generated source catalog</a></td></tr><tr><td>Compile a problem locally</td><td><a href="./quick-start.html">Quick start</a></td></tr><tr><td>Add a solution and record validation</td><td><a href="./conventions.html">Code and archive conventions</a>, <a href="./contributing.html">Contributing</a></td></tr><tr><td>Configure an editor and problem imports</td><td><a href="./tooling.html">Development tools</a></td></tr><tr><td>Update documentation or maintain the website</td><td><a href="./maintenance.html">Maintenance</a>, <a href="./pages.html">GitHub Pages maintenance</a></td></tr><tr><td>Browse all documentation topics</td><td><a href="./handbook.html">Documentation index</a></td></tr></tbody></table><p>The API documentation describes static JSON snapshots and external interfaces used by the website, not an online judging service. Download OpenAPI and JSON Schema contracts from the <a href="./api/">API reference</a>.</p><h2 id="branch-responsibilities" tabindex="-1">Branch responsibilities <a class="header-anchor" href="#branch-responsibilities" aria-label="Permalink to &quot;Branch responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Branch</th><th>Contents</th></tr></thead><tbody><tr><td><a href="https://github.com/xw7qwq/solutions/tree/main" target="_blank" rel="noreferrer"><code>main</code></a></td><td>Algorithm source code, templates, and existing development tools</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/tree/docs/project-guide" target="_blank" rel="noreferrer"><code>docs/project-guide</code></a></td><td>This branch: documentation source, API contracts, project conventions, and build checks</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/tree/gh-pages" target="_blank" rel="noreferrer"><code>gh-pages</code></a></td><td>Problem browser, data snapshots, and generated documentation in <code>docs/</code></td></tr></tbody></table><p>Documentation does not need to be merged into <code>main</code>. After a documentation PR merges into this branch, the workflow builds the site and updates only <code>gh-pages/docs/</code>. The source catalog records the default-branch commit it describes; see <a href="./maintenance.html">Maintenance</a> for refresh instructions.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><h3 id="read-and-check-markdown" tabindex="-1">Read and check Markdown <a class="header-anchor" href="#read-and-check-markdown" aria-label="Permalink to &quot;Read and check Markdown&quot;">​</a></h3><p>Read the documentation directly on GitHub or in a Markdown reader. The checker requires Git and Python 3.10+, with no third-party Python packages.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/project-guide</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/xw7qwq/solutions.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codeflare-docs</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codeflare-docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docs.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Keep complete Git history and remote branch references. Catalog and API checks read a recorded commit and <code>origin/gh-pages</code>. Compiling an individual solution requires its language toolchain; see <a href="./quick-start.html">Quick start</a>.</p><h3 id="preview-the-documentation-site" tabindex="-1">Preview the documentation site <a class="header-anchor" href="#preview-the-documentation-site" aria-label="Permalink to &quot;Preview the documentation site&quot;">​</a></h3><p>Run from the repository root with Node.js 22+ and npm:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:4174/docs/" target="_blank" rel="noreferrer">http://127.0.0.1:4174/docs/</a>. Stop the server with <code>Ctrl+C</code>.</p><p>The development server converts Markdown into <code>site/.content/</code> at startup. After editing source documents, run <code>npm --prefix site run prepare:docs</code> in another terminal to regenerate page content.</p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./repository.html">README.md</a>, <a href="./contributing.html">CONTRIBUTING.md</a></td><td>Project entry point and contribution guidelines</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/tree/docs/project-guide/docs/" target="_blank" rel="noreferrer">docs/</a></td><td>Guides, API documentation, and source catalog</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/scripts/docs.py" target="_blank" rel="noreferrer">scripts/docs.py</a></td><td>Markdown, relative link, heading anchor, and source catalog checks</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/scripts/README.md" target="_blank" rel="noreferrer">scripts/README.md</a>, <a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/archive/submissions.json" target="_blank" rel="noreferrer">archive/submissions.json</a></td><td>Archive tools, offline tests, and verified submission receipts</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/site/package.json" target="_blank" rel="noreferrer">site/package.json</a></td><td>Site dependencies and development and build commands</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/tree/docs/project-guide/site/.vitepress/" target="_blank" rel="noreferrer">site/.vitepress/</a></td><td>Site configuration and theme</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/tree/docs/project-guide/site/public/api/" target="_blank" rel="noreferrer">site/public/api/</a></td><td>OpenAPI and JSON Schema contracts</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/site/prepare.mjs" target="_blank" rel="noreferrer">site/prepare.mjs</a>, <a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/site/check-build.mjs" target="_blank" rel="noreferrer">site/check-build.mjs</a></td><td>Content conversion and build output checks</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/site/publish.mjs" target="_blank" rel="noreferrer">site/publish.mjs</a></td><td>Documentation publishing and live verification</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/.github/workflows/docs.yml" target="_blank" rel="noreferrer">.github/workflows/docs.yml</a></td><td>Documentation validation, build, and publishing workflow</td></tr><tr><td><a href="https://github.com/xw7qwq/solutions/blob/docs/project-guide/.github/workflows/archive.yml" target="_blank" rel="noreferrer">.github/workflows/archive.yml</a></td><td>Offline archive tests and source integrity audit</td></tr></tbody></table><p><code>site/.content/</code>, <code>site/.vitepress/dist/</code>, and <code>site/node_modules/</code> are generated directories. Edit Markdown sources and configuration, and keep generated directories out of commits. <a href="./structure.html">Project structure</a> and the <a href="./catalog.html">source catalog</a> define source categories and counts.</p><h2 id="validation-and-contributions" tabindex="-1">Validation and contributions <a class="header-anchor" href="#validation-and-contributions" aria-label="Permalink to &quot;Validation and contributions&quot;">​</a></h2><p>After installing site dependencies, run from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docs.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:api</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>These commands validate documentation and the catalog, API contracts and snapshots, the static site build, and whitespace. By default, API checks read two snapshots from local <code>origin/gh-pages</code>. They do not judge algorithms or establish that the remote site was deployed successfully.</p><p>Create a working branch from <code>docs/project-guide</code>, stage changes by path, and describe the reason, changes, and validation in a pull request. Track new Markdown files and local link targets in Git first. See <a href="./contributing.html">Contributing</a> for the full process.</p><h2 id="domain-and-deployment" tabindex="-1">Domain and deployment <a class="header-anchor" href="#domain-and-deployment" aria-label="Permalink to &quot;Domain and deployment&quot;">​</a></h2><p>CodeFlare uses <strong><a href="https://codeflare.lucius7.dev" target="_blank" rel="noreferrer">codeflare.lucius7.dev</a></strong>. Documentation is published under <a href="https://codeflare.lucius7.dev/docs/" target="_blank" rel="noreferrer">/docs/</a>, and the static API lives under <code>/data/</code>.</p><p>GitHub Pages should publish from the root of <code>gh-pages</code>, with <code>codeflare.lucius7.dev</code> as its custom domain. The publishing script validates the repository, source branch, and domain, then updates only the managed <code>docs/</code> directory, preserving the problem browser and domain configuration.</p><p>API collection <code>2.0.0</code> uses the new domain and the <code>xw7qwq/solutions</code> repository identity while retaining response field structures. See <a href="./api/standards.html">Errors and compatibility</a> for migration details. The source catalog retains its original commit SHA, timestamp, and counting rules.</p><p>The workflow checks every PR targeting <code>docs/project-guide</code> and every push to that branch. Only pushes publish. Verify releases through <a href="https://github.com/xw7qwq/solutions/actions" target="_blank" rel="noreferrer">Actions</a>, public pages, and <code>docs/build-info.json</code>; see <a href="./maintenance.html">Maintenance</a> for details.</p><h2 id="content-and-licensing" tabindex="-1">Content and licensing <a class="header-anchor" href="#content-and-licensing" aria-label="Permalink to &quot;Content and licensing&quot;">​</a></h2><p>Each algorithm source file is used independently; there is no single executable for the entire repository. The archive includes unfinished drafts and template fragments without <code>main</code>. A file&#39;s presence in Git or on a website does not mean it passed an online judge. Consult the original judge for the problem statement.</p><p>The repository has no single declared open-source license. Retain attribution and follow the applicable licenses when using problem statements, third-party code, or dependencies. This documentation grants no additional permissions.</p><h2 id="related-projects" tabindex="-1">Related projects <a class="header-anchor" href="#related-projects" aria-label="Permalink to &quot;Related projects&quot;">​</a></h2><p><a href="https://github.com/xw7qwq/ojflare" target="_blank" rel="noreferrer">OJFlare</a> uses <a href="https://ojflare.lucius7.dev" target="_blank" rel="noreferrer">ojflare.lucius7.dev</a> and is maintained and deployed separately.</p>`,37)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
